package com.comandos.transfer.service;import com.comandos.core.service.UnitScopeGuard;import jakarta.persistence.EntityManager;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import org.springframework.web.server.ResponseStatusException;
@Component public class TransferUnitScopeGuard implements UnitScopeGuard{private final EntityManager em;public TransferUnitScopeGuard(EntityManager em){this.em=em;}public void validateOrganizationChange(long unitId,long organizationId){long n=em.createQuery("select count(t) from InventoryTransfer t where (t.sourceUnitLegacyId=:unit or t.destinationUnitLegacyId=:unit) and t.organizationLegacyId<>:organization",Long.class).setParameter("unit",unitId).setParameter("organization",organizationId).getSingleResult();if(n>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The unit has transfer records in its current organization.");}}
